// src/Component/UserList.js
import React, { useEffect, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import {
  fetchUsersAsync,
  createUserAsync,
  updateUserAsync,
  deleteUserAsync,
  selectUsersState,
} from "./userSlice";
import "./UserList.css";

function UserList() {
  const dispatch = useDispatch();
  const { users, loading, error } = useSelector(selectUsersState);

  const [editUserId, setEditUserId] = useState(null);
  const [editData, setEditData] = useState({});
  const [showAddForm, setShowAddForm] = useState(false);
  const [newUser, setNewUser] = useState({
    username: "",
    email: "",
    first_name: "",
    last_name: "",
    profile: { bio: "", phone: "" },
    is_active: true,
  });

  // Pagination
  const [currentPage, setCurrentPage] = useState(1);
  const usersPerPage = 5;
  const totalPages = Math.ceil(users.length / usersPerPage);

  useEffect(() => {
    dispatch(fetchUsersAsync());
  }, [dispatch]);

  // Handle input changes
  const handleChange = (key, value, isEdit = false) => {
    if (key === "bio" || key === "phone") {
      isEdit
        ? setEditData({ ...editData, profile: { ...editData.profile, [key]: value } })
        : setNewUser({ ...newUser, profile: { ...newUser.profile, [key]: value } });
    } else if (key === "is_active") {
      isEdit
        ? setEditData({ ...editData, [key]: value })
        : setNewUser({ ...newUser, [key]: value });
    } else {
      isEdit
        ? setEditData({ ...editData, [key]: value })
        : setNewUser({ ...newUser, [key]: value });
    }
  };

  // Save edited user
  const handleSave = async () => {
    if (!editUserId) return;
    try {
      await dispatch(updateUserAsync(editData)).unwrap();
      await dispatch(fetchUsersAsync());
      setEditUserId(null);
      alert("✅ User updated successfully");
    } catch (err) {
      console.error(err);
      alert(`Update failed: ${err?.detail || JSON.stringify(err)}`);
    }
  };

  // Add new user
  const handleAddUser = async () => {
    try {
      await dispatch(createUserAsync(newUser)).unwrap();
      await dispatch(fetchUsersAsync());
      setShowAddForm(false);
      setNewUser({
        username: "",
        email: "",
        first_name: "",
        last_name: "",
        profile: { bio: "", phone: "" },
        is_active: true,
      });
      alert("✅ User created successfully");
    } catch (err) {
      console.error(err);
      alert(`Create failed: ${err?.detail || JSON.stringify(err)}`);
    }
  };

  // Delete user
  const handleDelete = async (id) => {
    if (!id) return;
    if (window.confirm("Are you sure you want to delete this user?")) {
      try {
        await dispatch(deleteUserAsync(id)).unwrap();
        await dispatch(fetchUsersAsync());
        alert("User deleted successfully!");
      } catch (err) {
        console.error(err);
        alert(`Delete failed: ${err?.detail || JSON.stringify(err)}`);
      }
    }
  };

  // ✅ Export all users
  const handleExportAll = async () => {
    const confirmDownload = window.confirm("Do you want to download all users as Excel?");
    if (!confirmDownload) return;

    try {
      const token = localStorage.getItem("access_token");
      const response = await fetch("http://localhost:8000/api/export-users/", {
        method: "GET",
        headers: {
          Authorization: `Bearer ${token}`,
          Accept: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        },
      });

      if (!response.ok) throw new Error(`Failed to download file (Status: ${response.status})`);

      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = "All_Users_Report.xlsx";
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.URL.revokeObjectURL(url);
    } catch (err) {
      alert("Error downloading file: " + err.message);
    }
  };

  // Pagination logic
  const indexOfLastUser = currentPage * usersPerPage;
  const indexOfFirstUser = indexOfLastUser - usersPerPage;
  const currentUsers = users.slice(indexOfFirstUser, indexOfLastUser);

  if (loading) return <p>Loading users...</p>;
  if (error)
    return (
      <p style={{ color: "red" }}>
        Error: {typeof error === "string" ? error : error.detail || JSON.stringify(error)}
      </p>
    );

  return (
    <div className="userlist-container">
      <h2>User Management</h2>

      {/* Buttons */}
      <div className="button-group">
        <button className="add-user-btn" onClick={() => setShowAddForm((prev) => !prev)}>
          {showAddForm ? "Cancel" : "Add User"}
        </button>
        <button className="export-all-btn" onClick={handleExportAll}>
          Export All Users
        </button>
      </div>

      {/* Add User Form */}
      {showAddForm && (
        <div className="add-user-form">
          <input placeholder="Username" value={newUser.username} onChange={(e) => handleChange("username", e.target.value)} />
          <input placeholder="Email" value={newUser.email} onChange={(e) => handleChange("email", e.target.value)} />
          <input placeholder="First Name" value={newUser.first_name} onChange={(e) => handleChange("first_name", e.target.value)} />
          <input placeholder="Last Name" value={newUser.last_name} onChange={(e) => handleChange("last_name", e.target.value)} />
          <input placeholder="Bio" value={newUser.profile.bio} onChange={(e) => handleChange("bio", e.target.value)} />
          <input placeholder="Phone" value={newUser.profile.phone} onChange={(e) => handleChange("phone", e.target.value)} />
          <select value={newUser.is_active ? "Active" : "Inactive"} onChange={(e) => handleChange("is_active", e.target.value === "Active")}>
            <option>Active</option>
            <option>Inactive</option>
          </select>
          <button className="save-btn" onClick={handleAddUser}>Save</button>
        </div>
      )}

      {/* User Table */}
      <table className="user-table">
        <thead>
          <tr>
            <th>ID</th>
            <th>Username</th>
            <th>Email</th>
            <th>First Name</th>
            <th>Last Name</th>
            <th>Bio</th>
            <th>Phone</th>
            <th>Status</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {currentUsers.length > 0 ? (
            currentUsers.map((u) => (
              <tr key={u.id}>
                <td>{u.id}</td>
                <td>{editUserId === u.id ? <input type="text" value={editData.username || ""} onChange={(e) => handleChange("username", e.target.value, true)} /> : u.username}</td>
                <td>{editUserId === u.id ? <input type="text" value={editData.email || ""} onChange={(e) => handleChange("email", e.target.value, true)} /> : u.email}</td>
                <td>{editUserId === u.id ? <input type="text" value={editData.first_name || ""} onChange={(e) => handleChange("first_name", e.target.value, true)} /> : u.first_name}</td>
                <td>{editUserId === u.id ? <input type="text" value={editData.last_name || ""} onChange={(e) => handleChange("last_name", e.target.value, true)} /> : u.last_name}</td>
                <td>{editUserId === u.id ? <input type="text" value={editData.profile?.bio || ""} onChange={(e) => handleChange("bio", e.target.value, true)} /> : u.profile?.bio || ""}</td>
                <td>{editUserId === u.id ? <input type="text" value={editData.profile?.phone || ""} onChange={(e) => handleChange("phone", e.target.value, true)} /> : u.profile?.phone || ""}</td>
                <td>{editUserId === u.id ? <select value={editData.is_active ? "Active" : "Inactive"} onChange={(e) => handleChange("is_active", e.target.value === "Active", true)}><option>Active</option><option>Inactive</option></select> : u.is_active ? "Active" : "Inactive"}</td>
                <td>
                  {editUserId === u.id ? (
                    <div className="inline-btns">
                      <button className="save-btn" onClick={handleSave}>Save</button>
                      <button className="cancel-btn" onClick={() => setEditUserId(null)}>Cancel</button>
                    </div>
                  ) : (
                    <div className="inline-btns">
                      <button className="edit-btn" onClick={() => { setEditUserId(u.id); setEditData({ ...u }); }}>Edit</button>
                      <button className="delete-btn" onClick={() => handleDelete(u.id)}>Delete</button>
                    </div>
                  )}
                </td>
              </tr>
            ))
          ) : (
            <tr>
              <td colSpan="9" style={{ textAlign: "center" }}>No users found</td>
            </tr>
          )}
        </tbody>
      </table>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="pagination">
          {Array.from({ length: totalPages }, (_, i) => (
            <button key={i + 1} className={currentPage === i + 1 ? "active-page" : ""} onClick={() => setCurrentPage(i + 1)}>
              {i + 1}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

export default UserList;
